window.AUTH=window.AUTH||{};window.AUTH["24-758"]={"d":"24-758","id":"2025/24-758","n":"The GEO Group, Inc. v. Menocal","briefs":[{"k":"petitioner","label":"Brief of petitioner The GEO Group, Inc.","date":"2025-07-31","url":"https://www.supremecourt.gov/DocketPDF/24/24-758/368554/20250731150752009_24-758%20Brief%20for%20Petitioner.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondents Alejandro Menocal, et al.","date":"2025-09-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-758/374721/20250915201017854_Menocal.Response%20Brief.pdf","side":"res","n":70},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-09-22","url":"https://www.supremecourt.gov/DocketPDF/24/24-758/375567/20250922190811671_24-758%20bsacUS%20%20GEOGroup%20final.pdf","side":"us","n":64},{"k":"reply","label":"Reply of petitioner The GEO Group, Inc.","date":"2025-10-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-758/379722/20251015151252617_24-758%20Reply%20Brief.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us2r15_bqmc.pdf","tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"op":10,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 25, 33, 41, 42","1":"44","2":"10, 15, 22"}},{"t":"case","label":"ACT, Inc. v. Worldwide Interactive Network, Inc.","cite":"46 F.4th 489","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/489/","by":{"0":"46","2":"29"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Assn. v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Bivens v. Six Unknown Agents","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Boyle v. United Techs. Corp.","cite":"487 U.S. 500","y":1988,"id":"1987/86-492","sc":1,"sum":"In a 5-to4 decision, the Court held that despite the absence of specific legislation immunizing government contractors from liability for design flaws, questions of their liability are of unique federal concern. As such, to the extent that it holds military contractors liable for design flaws, state law may significantly conflict with federal interests thereby requiring its displacement.","sumSrc":"Oyez","by":{"0":"45","3":"5"}},{"t":"case","label":"Brady v. Roosevelt S.S. Co.","cite":"317 U.S. 575","y":1943,"id":"scdb/1942-048","sc":1,"op":4,"ar":5,"sum":"1. An action to recover for a death resulting from injuries sustained when a rung of a ladder broke as the decedent, a United States customs inspector in the course of his official duties, was climbing.to board a vessel docked at a pier, is within the admiralty jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"1, 3, 12, 16, 17, 23","1":"7, 22, 26, 27, 29, 35, 42","2":"16, 17, 26","3":"3, 5, 7, 8, 15"}},{"t":"case","label":"Cabalce v. Thomas E. Blanchard & Assocs.","cite":"797 F.3d 720","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/720/","by":{"0":"9","3":"25"}},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"577 U.S. 153","y":2016,"id":"2015/14-857","sc":1,"op":6,"ar":8,"sum":"Concluding that the lower court had jurisdiction over a case before determining whether Yearsley applied.","sumSrc":"opinion","by":{"0":"1, 2, 9, 11, 15, 23, 24, 31, 37, 46","1":"2, 9, 16, 26, 29, 30, 36, 37, 41, 42","2":"16, 19, 21, 22, 26","3":"1-6, 8, 12, 15, 18, 19, 15"}},{"t":"case","label":"Chamberlain v. Clayton","cite":"56 Iowa 331","y":1881,"url":"https://www.courtlistener.com/c/Iowa/56/331/","by":{"0":"21"}},{"t":"case","label":"Cohen v. Beneficial Life Ins. Co.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"op":31,"ar":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10-13, 25, 28, 32, 34-38, 40-42","1":"1, 11, 12, 39","2":"2, 5, 10","3":"4, 16, 17, 19, 26"}},{"t":"case","label":"Digital Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"op":6,"ar":3,"sum":"Holding that a lower court's refusal Alito, J., concurring in judgment to enforce a settlement agreement against a plaintiff 's claims was not a collateral order.","sumSrc":"opinion","by":{"0":"32, 42","1":"1, 11, 20, 21, 27, 32, 36","2":"10, 13, 14"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Filarsky v. Delia","cite":"566 U.S. 377","y":2012,"id":"2011/10-1018","sc":1,"op":1,"ar":7,"sum":"The Court found that a private attorney retained by a governmental agency is not prevented from claiming qualified immunity simply because they are not a full-time employee of the agency.","sumSrc":"Oyez","by":{"0":"1, 3, 11, 12, 14, 15, 18, 21-23, 27, 29, 30, 42-48","1":"30, 31","2":"20, 22-24","3":"1-3, 10, 11, 12-14, 16, 22-24, 26, 12"}},{"t":"case","label":"Gregory v. Brooks","cite":"37 Conn. 365","y":1870,"url":"https://www.courtlistener.com/c/Conn./37/365/","by":{"0":"21"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"op":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"0":"2, 15, 26, 27, 31, 40"}},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"op":7,"sum":"Mandamus was not the appropriate means of challenging the validity of the indictment on the ground that it violated the Speech or Debate Clause. Direct appeal to the Court of Appeals was available and was the proper course.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26, 31","2":"14"}},{"t":"case","label":"Henderson v. Smith","cite":"26 W.Va. 829","y":1885,"url":"https://www.courtlistener.com/c/W.Va./26/829/","by":{"0":"21"}},{"t":"case","label":"Jenkins v. Waldron","cite":"11 Johns. 114","y":1814,"court":"N.Y. Sup.Ct.","url":"https://www.courtlistener.com/c/Johns./11/114/","by":{"0":"21"}},{"t":"case","label":"Johnson v. Jones","cite":"515 U.S. 304","y":1995,"id":"1994/94-455","sc":1,"sum":"The Court held that a defendant, who is entitled to invoke a qualified immunity defense, may not appeal a District Court's summary judgment order insofar as that order determines whether or not the pretrial record sets forth a genuine issue of fact for trial.","sumSrc":"Oyez","by":{"0":"36, 39","1":"20, 37, 38-41, 44-48","2":"10, 25","3":"25"}},{"t":"case","label":"Lamar v. Browne","cite":"92 U.S. 187","y":1875,"id":"scdb/1875-160","sc":1,"ar":2,"by":{"0":"19, 20","1":"24, 25, 28","3":"9"}},{"t":"case","label":"McMahon v. Presidential Airways, Inc.","cite":"502 F.3d 1331","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/502/1331/","by":{"0":"46","2":"29"}},{"t":"case","label":"Menocal v. GEO Grp., Inc.","cite":"113 F. Supp. 3d 1125","y":2015,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/113/1125/","by":{"0":"8"}},{"t":"case","label":"Merck Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"op":11,"sum":"Explaining that the avoidance of distraction, overdeterrence, and timidity in Government service justifed immediate appeals of orders denying qualifed immunity.","sumSrc":"opinion","by":{"0":"12, 14, 15, 25-31, 33-44, 47","1":"12, 32, 44, 45","2":"13, 15, 20, 27, 28","3":"1, 2, 7, 10, 11, 13, 14, 17-19, 21, 23, 25"}},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Imp. Co.","cite":"59 U.S. 272","y":1855,"id":"1850-1900/59us272","sc":1,"sum":"The Court found that \"due process of law\" meant that all citizens be tried \"by the law of the land,\" a concept established by the Magna Carta.","sumSrc":"Oyez","by":{"0":"18-19, 24, 42","1":"25, 28","3":"10"}},{"t":"case","label":"Newman v. Bradley Contracting Co.","cite":"164 N.Y.S. 757","y":1917,"court":"App. Term","url":"https://www.courtlistener.com/c/N.Y.S./164/757/","by":{"0":"20"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"op":2,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"14, 25-27, 31, 44","2":"14, 22","3":"7, 11, 21"}},{"t":"case","label":"North Carolina v. Gosnell","cite":"74 F. 734","y":1896,"court":"C.C.W.D.N.C.","url":"https://www.courtlistener.com/c/F./74/734/","by":{"0":"18"}},{"t":"case","label":"Puerto Rico Aqueduct & Sewer Authority v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"op":4,"ar":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 11-14, 27","2":"14, 22","3":"2, 4, 16, 17"}},{"t":"case","label":"28, 30-33, 41, 44 Rail v. Potts & Baker","cite":"27 Tenn. 225","y":1847,"url":"https://www.courtlistener.com/c/Tenn./27/225/","by":{"0":"21"}},{"t":"case","label":"Reed v. Rice","cite":"25 Ky. 44","y":1829,"court":"App.","url":"https://www.courtlistener.com/c/Ky./25/44/","by":{"0":"18","1":"24"}},{"t":"case","label":"Richardson v. McKnight","cite":"521 U.S. 399","y":1997,"id":"1996/96-318","sc":1,"op":2,"sum":"The Court held that prison guards employed by a private firm are not entitled to a qualified immunity from suit by prisoners charging a section 1983 violation.","sumSrc":"Oyez","by":{"0":"21, 22, 43","1":"30, 31, 34, 35","2":"20, 24","3":"22-23"}},{"t":"case","label":"Robinson v. State","cite":"93 Ga. 77","y":1893,"url":"https://www.courtlistener.com/c/Ga./93/77/","by":{"0":"18"}},{"t":"case","label":"Salliote v. Knight Bridge Co.","cite":"122 F. 378","y":1903,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./122/378/","ar":1,"by":{"0":"20","1":"28","3":"8, 9"}},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1952,"id":"scdb/1951-001","sc":1,"op":2,"sum":"Bail has not been fixed by proper methods in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"State v. Mooring","cite":"115 N.C. 709","y":1894,"url":"https://www.courtlistener.com/c/N.C./115/709/","by":{"0":"18"}},{"t":"case","label":"United States v. Brewster","cite":"408 U.S. 501","y":1972,"id":"1971/70-45","sc":1,"sum":"Appellee, a former United States Senator, was charged with the solicitation and acceptance of bribes in violation of 18 U. S. C. §§ 201 (c) (1) and 201 (g). T-he District Court, on appellee's pretrial motion, dismissed the indictment on the ground that the Speech or Debate Clause of the Constitution shielded him \"from any prosecution for alleged bribery to perform a legislative act.\" The United States filed a direct …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"United States v. Lynah","cite":"188 U.S. 445","y":1903,"id":"scdb/1902-064","sc":1,"sum":"All private property is held subject to the necessities of government and the right of eminent domain underlies all such rights of property.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"United States v. Mitchell","cite":"445 U.S. 535","y":1980,"id":"1979/78-1756","sc":1,"sum":"The General Allotment Act cannot be read as establishing that the United States has a fiduciary responsibility for management of allotted forest lands, and thus does not provide respondents with a cause of action for the damages sought.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"op":7,"ar":5,"sum":"Holding that the interest in shortening troublesome litiga- Page Proof Pending Publication tion is insuffcient to treat a defense as an immunity.","sumSrc":"opinion","by":{"0":"10, 34, 42","1":"3, 11-13, 18, 20, 21, 30-32, 35, 37, 44, 48","2":"10, 12, 14, 21, 22, 27, 28, 32","3":"21, 23"}},{"t":"case","label":"Williams v. Adams","cite":"85 Mass. 171","y":1861,"url":"https://www.courtlistener.com/c/Mass./85/171/","by":{"0":"22"}},{"t":"case","label":"Wyatt v. Cole","cite":"504 U.S. 158","y":1992,"id":"1991/91-126","sc":1,"sum":"With the assistance of respondent Robbins, an attorney, respondent Cole filed a complaint under the Mississippi replevin statute against his partner, petitioner Wyatt. After Cole refused to comply with a state court order to return to Wyatt property seized under the statute, Wyatt brought suit in the Federal District Court under 42 U. S. C. § 1983, challenging the state statute's constitutionality and seeking …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Yearsley v. W.A. Ross Constr. Co.","cite":"309 U.S. 18","y":1940,"id":"scdb/1939-057","sc":1,"op":68,"ar":34,"sum":"Noting without disagreement that the lower court exercised jurisdiction over the case.","sumSrc":"opinion","by":{"0":"1, 2, 10, 12, 16-20, 22-24, 29, 31, 33, 35, 37-40, 46, 49, 50","1":"2, 8, 9, 17, 21, 24-26, 30, 41","2":"2, 4, 6, 17-19, 21, 22, 25","3":"12"}},{"t":"const","label":"Article I, Section 8, Clause 4","clauses":[["naturalization-bankruptcy","Naturalization and Bankruptcy Clause"]],"text":"To establish an uniform Rule of Naturalization, and uniform Laws on the subject of Bankruptcies throughout the United States;","by":{"0":"1, 48"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"0":"2, 14, 25, 27, 31, 33, 37, 41","2":"6, 14, 22","3":"17"}},{"t":"usc","label":"6 U.S.C. § 112","url":"https://www.law.cornell.edu/uscode/text/6/112","subs":["(b)(2)"],"stext":{"head":"§112. Secretary; functions","paras":[[0,"(a) Secretary"],[0,"(1) In general"],[1,"There is a Secretary of Homeland Security, appointed by the President, by and with the advice and consent of the Senate."],[0,"(2) Head of Department"],[1,"The Secretary is the head of the Department and shall have direction, authority, and control over it."],[0,"(3) Functions vested in Secretary"],[1,"All functions of all officers, employees, and organizational units of the Department are vested in the Secretary."],[0,"(b) Functions"],[0,"The Secretary—"],[1,"(1) except as otherwise provided by this chapter, may delegate any of the Secretary's functions to any officer, employee, or organizational unit of the Department;"],[1,"(2) shall have the authority to make contracts, grants, and cooperative agreements, and to enter into agreements with other executive agencies, as may be necessary and proper to carry out the Secretary's responsibilities under this chapter or otherwise provided by law; and"],[1,"(3) shall take reasonable steps to ensure that information systems and databases of the Department are compatible with each other and with appropriate databases of other Departments."],[0,"(c) Coordination with non-Federal entities"],[0,"With respect to homeland security, the Secretary shall coordinate through the Office of State and Local Coordination 1 (established under section 361 of this title) (including the provision of training and equipment) with State and local government personnel, agencies, and authorities, with the private sector, and with other entities, including by—"],[1,"(1) coordinating with State and local government personnel, agencies, and authorities, and with the private sector, to ensure adequate planning, equipment, training, and exercise activities;"],[1,"(2) coordinating and, as appropriate, consolidating, the Federal Government's communications and systems of communications relating to homeland security with State and local government personnel, agencies, and authorities, the private sector, other entities, and the public; and"],[1,"(3) distributing or, as appropriate, coordinating the distribution of, warnings and information to State and local government personnel, agencies, and authorities and to the public."],[0,"(d) Meetings of National Security Council"],[0,"The Secretary may, subject to the direction of the President, attend and participate in meetings of the National Security Council."],[0,"(e) Issuance of regulations"],[0,"The issuance of regulations by the Secretary shall be governed by the provisions of chapter 5 of title 5, except as specifically provided in this chapter, in laws granting regulatory authorities that are transferred by this chapter, and in laws enacted after November 25, 2002."],[0,"(f) Special Assistant to the Secretary"],[0,"The Secretary shall appoint a Special Assistant to the Secretary who shall be responsible for—"],[1,"(1) creating and fostering strategic communications with the private sector to enhance the primary mission of the Department to protect the American homeland;"],[1,"(2) advising the Secretary on the impact of the Department's policies, regulations, processes, and actions on the private sector;"],[1,"(3) interfacing with other relevant Federal agencies with homeland security missions to assess the impact of these agencies' actions on the private sector;"],[1,"(4) creating and managing private sector advisory councils composed of representatives of industries and associations designated by the Secretary to—"],[2,"(A) advise the Secretary on private sector products, applications, and solutions as they relate to homeland security challenges;"],[2,"(B) advise the Secretary on homeland security policies, regulations, processes, and actions that affect the participating industries and associations; and"],[2,"(C) advise the Secretary on private sector preparedness issues, including effective methods for—"],[3,"(i) promoting voluntary preparedness standards to the private sector; and"],[3,"(ii) assisting the private sector in adopting voluntary preparedness standards;"],[1,"(5) working with Federal laboratories, federally funded research and development centers, other federally funded organizations, academia, and the private sector to develop innovative approaches to address homeland security challenges to produce and deploy the best available technologies for homeland security missions;"],[1,"(6) promoting existing public-private partnerships and developing new public-private partnerships to provide for collaboration and mutual support to address homeland security challenges;"],[1,"(7) assisting in the development and promotion of private sector best practices to secure critical infrastructure;"],[1,"(8) providing information to the private sector regarding voluntary preparedness standards and the business justification for preparedness and promoting to the private sector the adoption of voluntary preparedness standards;"],[1,"(9) coordinating industry efforts, with respect to functions of the Department of Homeland Security, to identify private sector resources and capabilities that could be effective in supplementing Federal, State, and local government agency efforts to prevent or respond to a terrorist attack;"],[1,"(10) coordinating with the Commissioner of U.S. Customs and Border Protection and the Assistant Secretary for Trade Development of the Department of Commerce on issues related to the travel and tourism industries; and"],[1,"(11) consulting with the Office of State and Local Government Coordination and Preparedness on all matters of concern to the private sector, including the tourism industry."],[0,"(g) Standards policy"],[0,"All standards activities of the Department shall be conducted in accordance with section 12(d) of the National Technology Transfer Advancement Act of 1995 (15 U.S.C. 272 note) and Office of Management and Budget Circular A–119."],[0,"(h) Planning requirements"],[0,"The Secretary shall ensure the head of each office and component of the Department takes into account the needs of children, including children within under-served communities, in mission planning and mission execution. In furtherance of this subsection, the Secretary shall require each such head to seek, to the extent practicable, advice and feedback from organizations representing the needs of children. The Federal Advisory Committee Act (5 U.S.C. App.) 2 shall not apply whenever such advice or feedback is sought in accordance with this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/112?type=usc&year=mostrecent&link-type=html"},"head":"§112. Secretary; functions","tname":"Domestic Security","by":{"0":"6, 48","2":"3"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"5"}},{"t":"usc","label":"8 U.S.C. § 1555","url":"https://www.law.cornell.edu/uscode/text/8/1555","subs":["(d)"],"by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(g)","(g)(1)","(g)(2)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"4-5, 39, 44, 5, 48, 1, 6, 13, 49","1":"36","2":"3"}},{"t":"usc","label":"18 U.S.C. § 1589","url":"https://www.law.cornell.edu/uscode/text/18/1589","stext":{"head":"§1589. Forced labor","paras":[[0,"(a) Whoever knowingly provides or obtains the labor or services of a person by any one of, or by any combination of, the following means—"],[1,"(1) by means of force, threats of force, physical restraint, or threats of physical restraint to that person or another person;"],[1,"(2) by means of serious harm or threats of serious harm to that person or another person;"],[1,"(3) by means of the abuse or threatened abuse of law or legal process; or"],[1,"(4) by means of any scheme, plan, or pattern intended to cause the person to believe that, if that person did not perform such labor or services, that person or another person would suffer serious harm or physical restraint,"],[0,"shall be punished as provided under subsection (d)."],[0,"(b) Whoever knowingly benefits, financially or by receiving anything of value, from participation in a venture which has engaged in the providing or obtaining of labor or services by any of the means described in subsection (a), knowing or in reckless disregard of the fact that the venture has engaged in the providing or obtaining of labor or services by any of such means, shall be punished as provided in subsection (d)."],[0,"(c) In this section:"],[1,"(1) The term \"abuse or threatened abuse of law or legal process\" means the use or threatened use of a law or legal process, whether administrative, civil, or criminal, in any manner or for any purpose for which the law was not designed, in order to exert pressure on another person to cause that person to take some action or refrain from taking some action."],[1,"(2) The term \"serious harm\" means any harm, whether physical or nonphysical, including psychological, financial, or reputational harm, that is sufficiently serious, under all the surrounding circumstances, to compel a reasonable person of the same background and in the same circumstances to perform or to continue performing labor or services in order to avoid incurring that harm."],[0,"(d) Whoever violates this section shall be fined under this title, imprisoned not more than 20 years, or both. If death results from a violation of this section, or if the violation includes kidnaping, an attempt to kidnap, aggravated sexual abuse, or an attempt to kill, the defendant shall be fined under this title, imprisoned for any term of years or life, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1589?type=usc&year=mostrecent&link-type=html"},"head":"§1589. Forced labor","tname":"Crimes and Criminal Procedure","by":{"0":"8","2":"4"}},{"t":"usc","label":"18 U.S.C. § 1595","url":"https://www.law.cornell.edu/uscode/text/18/1595","stext":{"head":"§1595. Civil remedy","paras":[[0,"(a) An individual who is a victim of a violation of this chapter may bring a civil action against the perpetrator (or whoever knowingly benefits, or attempts or conspires to benefit, financially or by receiving anything of value from participation in a venture which that person knew or should have known has engaged in an act in violation of this chapter) in an appropriate district court of the United States and may recover damages and reasonable attorneys fees."],[0,"(b)(1) Any civil action filed under subsection (a) shall be stayed during the pendency of any criminal action arising out of the same occurrence in which the claimant is the victim."],[0,"(2) In this subsection, a \"criminal action\" includes investigation and prosecution and is pending until final adjudication in the trial court."],[0,"(c) No action may be maintained under subsection (a) unless it is commenced not later than the later of—"],[1,"(1) 10 years after the cause of action arose; or"],[1,"(2) 10 years after the victim reaches 18 years of age, if the victim was a minor at the time of the alleged offense."],[0,"(d) In any case in which the attorney general of a State has reason to believe that an interest of the residents of that State has been or is threatened or adversely affected by any person who violates section 1591, the attorney general of the State, as parens patriae, may bring a civil action against such person on behalf of the residents of the State in an appropriate district court of the United States to obtain appropriate relief."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1595?type=usc&year=mostrecent&link-type=html"},"head":"§1595. Civil remedy","tname":"Crimes and Criminal Procedure","by":{"0":"8","2":"4"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":1,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"10, 13, 32","1":"1, 11, 19","2":"1, 2, 4-6","3":"25, 26"}},{"t":"usc","label":"38 U.S.C. § 1703","url":"https://www.law.cornell.edu/uscode/text/38/1703","by":{"0":"46"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"22, 39","2":"23","3":"20"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","by":{"0":"47"}},{"t":"usc","label":"44 U.S.C. § 3554","url":"https://www.law.cornell.edu/uscode/text/44/3554","by":{"0":"46"}},{"t":"reg","label":"8 C.F.R. § 235.3","url":"https://www.ecfr.gov/current/title-8/section-235.3","subs":["(e)"],"by":{"0":"6"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"1":"4, 5, 6"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"12, 44"}},{"t":"case","label":"Burnett v. New York Central Railroad Co.","cite":"380 U.S. 424","y":1965,"id":"1964/437","sc":1,"sum":"Where a timely FELA action is begun in a state court having jurisdiction, the defendant is served with process, and the case is dismissed for improper venue, the FELA time limitation is tolled during the pendency of the state suit and until the state court order dismissing the action becomes final. Pp. 426-436. 332 F. 2d 529, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Burt v. Henderson","cite":"238 S.W. 626","y":1922,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W./238/626/","by":{"1":"29"}},{"t":"case","label":"Canter v. American Insurance Co.","cite":"28 U.S. 307","y":1830,"id":"scdb/1830-018","sc":1,"sum":"The libellants, in their original libel in the district court of the United States for the district of South Carolina; prayed that certain bales of cotton might be decreed to them with damages and costs. Canter, who also claimed tire cotton, prayed the court for restitution, with damages.and costs.- The district court decreed restitution of part of the cotton to the libellants, and dismissed the libel, without any …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"10, 12"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"sum":"1. In a proceeding instituted by a petition in the District Court for the condemnation of land under the War Purposes Act of 1917, a \"judgment\" entered upon a declaration of taking filed pursuant to the Declaration of Taking Act of 1931, and a subsequent order denying the landowner's motion to vacate the judgment and to dismiss the petition, held not \"final decisions\" under § 128 of the Judicial Code and therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Central Green Co. v. United States","cite":"531 U.S. 425","y":2001,"id":"2000/99-859","sc":1,"sum":"The Court held that in determining whether, under the Flood Control Act of 1928, immunity attaches, courts should consider the character of the waters that caused the relevant damage and the purposes behind their release rather than the relation between that damage and a flood control project.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Clark v. Louisville-Jefferson County Metro Government","cite":"130 F.4th 571","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/130/571/","by":{"1":"45"}},{"t":"case","label":"Cobbledick v. United States","cite":"309 U.S. 323","y":1940,"id":"scdb/1939-076","sc":1,"op":6,"sum":"Noting without disagreement that the lower court exercised jurisdiction over the case.","sumSrc":"opinion","by":{"1":"10","2":"9, 10"}},{"t":"case","label":"Contango Operators, Inc. v. United States","cite":"9 F. Supp. 3d 735","y":2014,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/9/735/","sum":"Rejecting Yearsley defense because finding of negligence on the merits also invalidated the defense.","sumSrc":"brief:1","by":{"1":"42"}},{"t":"case","label":"Coopers & Lybrand v. Livesay","cite":"437 U.S. 463","y":1978,"id":"1977/76-1836","sc":1,"op":2,"ar":1,"sum":"Respondents, who had purchased securities in reliance on a prospectus, brought this action on behalf of themselves and a class of similarly situated purchasers, alleging that petitioner accounting firm had violated the federal securities laws. The District Court first certified the action as a class action under Fed. Rule Civ. Proc. 23, and then, after further proceedings, decertified the class. Respondents then …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"1","2":"11"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"sum":"The Court held that Bivens' limited holding may not be extended to confer a right of action for damages against private entities acting under color of federal law. The Court reasoned that the threat of suit against an individual's employer was not the kind of deterrence contemplated by the Bivens decision.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"Crawford v. Haller","cite":"111 U.S. 796","y":1884,"id":"scdb/1883-277","sc":1,"sum":"Practice..","sumSrc":"Headnote (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Cunningham v. Hamilton County","cite":"527 U.S. 198","y":1999,"id":"1998/98-727","sc":1,"sum":"The Court held that an order imposing sanctions on an attorney pursuant to Rule 37(a)(4) is not a \"final decision,\" even where the attorney no longer represents a party in the case. \"To permit an immediate appeal from such a sanctions order would undermine the very purposes of Rule 37(a), which was designed to protect courts and opposing parties from delaying or harassing tactics during the discovery process,\" Justice Thomas wrote for the Court.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"De Baker v. Southern California Railway Co.","cite":"39 P. 610","y":1895,"court":"Cal.","url":"https://www.courtlistener.com/c/P./39/610/","by":{"1":"29"}},{"t":"case","label":"Engler v. Aldridge","cite":"75 P.2d 290","y":1938,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/75/290/","by":{"1":"29"}},{"t":"case","label":"Faust v. Richland County","cite":"109 S.E. 151","y":1921,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./109/151/","by":{"1":"29"}},{"t":"case","label":"- vi - Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"sum":"The Court held that because the work of aides was critical to the performance of legislative tasks and duties, they were nothing less than legislators' \"alter egos\" and thus immune from subpoenas by the Speech and Debate Clause. Aides were exempted from grand jury questioning so long as Senators invoked the privilege on their behalf.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Gulfstream Aerospace Corp. v. Mayacamas Corp.","cite":"485 U.S. 271","y":1988,"id":"1987/86-1329","sc":1,"sum":"Petitioner sued respondent in state court for breach of contract. Respondent did not remove the action to federal court, but, one month later, filed a diversity action against petitioner in the Federal District Court for breach of the same contract. The District Court denied petitioner's motion to stay or dismiss the action before it, finding that the facts of the case fell short of those necessary to justify the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Hopkins v. Clemson Agricultural College of South Carolina","cite":"221 U.S. 636","y":1911,"id":"scdb/1910-168","sc":1,"op":3,"ar":1,"sum":"With the exception named in the constitution every State has absolute immunity from suit; and the Eleventh Amendment applies not only where the State is actually named as a party but where the suit is really against it although nominally against one of its officers.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"5, 6, 7, 22, 27, 29","3":"7, 9"}},{"t":"case","label":"James Stewart & Co. v. Sadrakula","cite":"309 U.S. 94","y":1940,"id":"scdb/1939-058","sc":1,"op":4,"sum":"Noting without disagreement that the lower court exercised jurisdiction over the case.","sumSrc":"opinion","by":{"1":"2, 7, 25"}},{"t":"case","label":"James v. Dravo Contracting Co.","cite":"302 U.S. 134","y":1937,"id":"scdb/1937-003","sc":1,"sum":"(1) The provision as to concurrent jurisdiction qualifies the provision giving consent, and applies to lands acquired by purchase or condemnation as well as to lands given by municipalities. P. 143. (2) The provision reserving merely the right to execute process, repeated from an earlier statute, does not derogate from the broader reservation of jurisdiction in the statute as amended.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7, 30"}},{"t":"case","label":"Johnson-Howard v. AECOM Special Missions Services, Inc.","cite":"2023 WL 6216604","y":2023,"court":"D. Md.","by":{"1":"36"}},{"t":"case","label":"Keifer & Keifer v. Reconstruction Financial Corp.","cite":"306 U.S. 381","y":1939,"id":"scdb/1938-149","sc":1,"op":2,"sum":"1. A Regional Agricultural Credit Corporation, chartered by the Reconstruction Finance Corporation by authority of § 201 (e) of the Emergency Relief and Construction Act of 1932, and which under that statute is government-financed and managed and empowered to make loans to farmers and stockmen for agricultural purposes or for raising and marketing livestock-held subject to suit. Pp. 392, et seq. Neither the statute …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6, 16, 22","3":"7"}},{"t":"case","label":"Larson v. Domestic & Foreign Commerce Corp.","cite":"337 U.S. 682","y":1949,"id":"scdb/1948-106","sc":1,"op":5,"ar":1,"sum":"The suit was one against the United States 4nd, in the absence of consent by the United States, the District Court was without jurisdiction. Pp. 684-705. 2.' In determining whether a suit nominally against an officer is against the officer individually or against the sovereign, the crucial qukestion is whether the relief sought is relief against the sovereign. Pp. 687-688. Statement of the Case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6, 23"}},{"t":"case","label":"- vii - Lewis v. Clarke","cite":"581 U.S. 155","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/155/","sc":1,"by":{"1":"6, 8, 23"}},{"t":"case","label":"McLish v. Roff","cite":"141 U.S. 661","y":1891,"id":"scdb/1891-036","sc":1,"sum":"Under section 5 of the Act of March 3, 1891, c. 517, 26 Stat..826, “ to establish Circuit Courts of Appeal,” etc., the appeal or writ of error which may be taken “ from the existing Circuit Courts direct to the Supreme Court,” “ in any case in which the jurisdiction of the court is in issue,’-’ can be taken only after final judgment; when the party against whom.it is rendered must elect whether he will take his writ …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"10"}},{"t":"case","label":"Mercantile National Bank v. Langdeau","cite":"371 U.S. 555","y":1963,"id":"1962/14_0","sc":1,"by":{"1":"27"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"582 U.S. 23","y":2017,"id":"2016/15-457","sc":1,"op":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"1":"10, 12, 13, 20, 37, 40, 45"}},{"t":"case","label":"Microsoft Corp. v. I4I Limited Partnership","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"op":1,"sum":"A district court order denying a defendant's motion to dismiss an indictment for an alleged violation of Rule 6(e) is not immediately appealable under § 1291. Since petitioners have not yet been sentenced, the District Court's order is not a final judgment ending the litigation on the merits. Moreover, whatever view is taken of the scope of Mechanik (an issue not resolved here), an order such as that at issue does …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32","2":"10, 11, 13"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"op":7,"ar":2,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"1":"1, 12, 13, 35, 38","2":"10, 12, 22, 29, 33"}},{"t":"case","label":"Newman v. Bradley Construction Co.","cite":"100 Misc. 1","y":1917,"url":"https://www.courtlistener.com/c/Misc./100/1/","by":{"1":"28"}},{"t":"case","label":"Pritt v. John Crane Inc.","cite":"636 F. Supp. 3d 253","y":2022,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/636/253/","by":{"1":"42"}},{"t":"case","label":"Pullman Construction Industries, Inc. v. United States","cite":"23 F.3d 1166","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/23/1166/","by":{"1":"27","3":"16"}},{"t":"case","label":"- viii - Reconstruction Financial Corp. v. J.G. Menihan Corp.","cite":"312 U.S. 81","y":1941,"id":"scdb/1940-055","sc":1,"by":{"1":"6"}},{"t":"case","label":"Rhoads Industries, Inc. v. Shoreline Foundation, Inc.","cite":"2022 WL 742486","y":2022,"court":"E.D. Pa.","by":{"1":"38"}},{"t":"case","label":"Richardson-Merrell, Inc. v. Koller","cite":"472 U.S. 424","y":1985,"id":"1984/84-127","sc":1,"op":8,"sum":"Explaining that the avoidance of distraction, overdeterrence, and timidity in Government service justifed immediate appeals of orders denying qualifed immunity.","sumSrc":"opinion","by":{"1":"41"}},{"t":"case","label":"Sinochem International Co. v. Malaysia International Shipping Corp.","cite":"549 U.S. 422","y":2007,"id":"2006/06-102","sc":1,"sum":"The Court ruled 9-0 that \"a court need not resolve whether it has [...] personal jurisdiction over the defendant if it determines that [...] a foreign tribunal is plainly the more suitable arbiter of the merits of the case.\" The opinion by Justice Ruth Bader Ginsburg held that while the first step of a court is normally to determine whether it has jurisdiction, a court can dismiss a case for forum non conveniens without establishing subject-matter or personal jurisdiction.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Sloan Shipyards Corp. v. United States Shipping Board Emergency Fleet Corp.","cite":"258 U.S. 549","y":1922,"id":"scdb/1921-112","sc":1,"op":2,"sum":"1. The Emergency Fleet Corporation, as originally created, had the powers of corporations under the laws of the District of Columbia, where it was incorporated, and was liable to be sued, there and elsewhere, upon its contracts and for its torts, notwithstanding the fact that it was a federal agency and that its stock was taken entirely by the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"2, 4, 6, 7, 22","2":"16, 17","3":"1, 7"}},{"t":"case","label":"Sunrise Farms, Inc. v. Sabre Energy Services, LLC","cite":"2020 WL 13589214","y":2020,"court":"N.D. Iowa","by":{"1":"36, 37"}},{"t":"case","label":"Swint v. Chambers County Commission","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"op":2,"ar":3,"sum":"The Eleventh Circuit lacked jurisdiction to rule on the county commission's liability at this interlocutory stage of the litigation and, accordingly, should have dismissed the commission's appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21","2":"21, 22, 23"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"6"}},{"t":"case","label":"United States v. California","cite":"507 U.S. 746","y":1993,"id":"1992/91-2003","sc":1,"sum":"The Court determined that regardless of the fact that the Federal Government reimburses WBEC for its taxes, the private company is still the taxpayer. And, the taxpayer had its opportunity to go to court and challenge the state taxes imposed upon it, and accepted the result.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"- ix - United States v. James","cite":"478 U.S. 597","y":1986,"id":"1985/85-434","sc":1,"sum":"Section 702c bars recovery against the Government in these cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"by":{"1":"7"}},{"t":"case","label":"United States v. MacDonald","cite":"435 U.S. 850","y":1978,"id":"1977/75-1892","sc":1,"sum":"A defendant may not, before trial, appeal a federal district court's order denying his motion to dismiss an indictment because of an alleged violation of his Sixth Amendment right to a speedy trial. Pp. 853-863. 531 F. 2d 196, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41","2":"11, 12"}},{"t":"case","label":"United States v. New Mexico","cite":"455 U.S. 720","y":1982,"id":"1981/80-702","sc":1,"sum":"The contractors, as independent taxable entities, are not protected by the Constitution's guarantee of federal supremacy, and hence are subject to the state taxes in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"United States v. The Paquete Habana","cite":"189 U.S. 453","y":1903,"id":"scdb/1902-146","sc":1,"ar":1,"sum":"This court having decided in The Paquete Habana, 175 U. S. 677, that certain fishing smacks engaged in coast fishing for the daily market were not liable to capture, and ordered that the proceeds of vessels and cargoes be restored to the claimants with compensatory and not punitive damages and costs, and it appearing that the damages allowed were excessive, the cases were remanded to the District Court for further …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24, 28"}},{"t":"case","label":"United States v. Wampler","cite":"624 F.3d 1330","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/624/1330/","by":{"1":"12"}},{"t":"case","label":"Van Cauwenberghe v. Biard","cite":"486 U.S. 517","y":1988,"id":"1987/87-336","sc":1,"op":7,"sum":"Neither an order denying a motion to dismiss on the ground that an extradited person is immune from civil process, nor an order denying such a motion on forum non conveniens grounds, is a collateral order subject to immediate appeal as a final judgment under § 1291.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 19, 26, 27, 39-42","2":"10-15"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)","(e)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"1":"18","2":"2, 3, 8, 28, 31, 32, 3, 8, 32"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(c)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"head":"§2072. Rules of procedure and evidence; power to prescribe","tname":"Judiciary and Judicial Procedure","by":{"1":"13","3":"25"}},{"t":"case","label":"Al Shimari v. CACI Premier Technology, Inc.","cite":"775 Fed. Appx. 758","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./775/758/","by":{"2":"31"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne International Drilling Co.","cite":"581 U.S. 170","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/170/","sc":1,"by":{"2":"15, 28"}},{"t":"case","label":"CACI Premier Technology, Inc. v. Al Shimari","cite":"141 S. Ct. 2850","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2850/","sc":1,"by":{"2":"1"}},{"t":"case","label":"Camreta v. Greene","cite":"563 U.S. 692","y":2011,"id":"2010/09-1454","sc":1,"op":1,"sum":"A case which the Court vacated in part and remanded in favor of the defendant without addressing the Fourth Amendment question at issue.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Flanagan v. United States","cite":"465 U.S. 259","y":1984,"id":"1983/82-374","sc":1,"sum":"The disqualification order was not immediately appealable under § 1291, and hence the Court of Appeals had no jurisdiction to review the order prior to entry of final judgment in the case.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Gingras v. Think Finance, Inc.","cite":"922 F.3d 112","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/922/112/","by":{"2":"15"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Lauro Lines s.r.l. v. Chasser","cite":"490 U.S. 495","y":1989,"id":"1988/88-23","sc":1,"op":1,"ar":1,"sum":"An interlocutory order denying a defendant's motion to dismiss a damages action on the basis of a contractual forum-selection clause is not immediately appealable under § 1291. Such an order is not final in the usual sense, for it does not end the litigation on the merits but, on the contrary, ensures that the litigation will continue. Nor does the order fall within the narrow exception to the normal application of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 14, 15, 23, 26, 31"}},{"t":"case","label":"Martin v. Halliburton","cite":"618 F.3d 476","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/618/476/","by":{"2":"32"}},{"t":"case","label":"Memorial Hospital v. Mercury Construction Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11, 11"}},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Improvement Co.","cite":"18 How. 272","y":1855,"url":"https://www.courtlistener.com/c/How./18/272/","by":{"2":"25, 26"}},{"t":"case","label":"Osborn v. Haley","cite":"549 U.S. 225","y":2007,"id":"2006/05-593","sc":1,"sum":"The Court upheld the Sixth Circuit and ruled that \"Westfall Act certification is proper when a federal officer charged with misconduct asserts, and the Attorney General concludes, that the incident or episode in suit never occurred.\" The opinion by Justice Ruth Bader Ginsburg held that the Act would be ineffective at shielding federal employees from suit if the government were required to accept for immunity purposes the plaintiff's allegation that the event in question occurred.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Owen v. City of Independence","cite":"445 U.S. 622","y":1980,"id":"1979/78-1779","sc":1,"sum":"A municipality has no immunity from liability under § 1983 flowing from its constitutional violations and may not assert the good faith of its officers as a defense to such liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Owino v. CoreCivic, Inc.","cite":"60 F.4th 437","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/437/","by":{"2":"32"}},{"t":"case","label":"Posada v. Cultural Care, Inc.","cite":"66 F.4th 348","y":2023,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/66/348/","by":{"2":"29"}},{"t":"case","label":"Procunier v. Navarette","cite":"434 U.S. 555","y":1978,"id":"1977/76-446","sc":1,"sum":"The Court of Appeals erred in reversing the District Court's summary judgment for petitioners.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Randolph v. Donaldson","cite":"9 Cranch 76","y":1815,"url":"https://www.courtlistener.com/c/Cranch/9/76/","by":{"2":"30"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"2":"15"}},{"t":"case","label":"Ritzen Group, Inc. v. Jackson Masonry, LLC","cite":"589 U.S. 35","y":2020,"id":"2019/18-938","sc":1,"op":1,"sum":"The Court held that a bankruptcy court’s order unreservedly denying relief from the automatic stay of creditor debt-collection efforts outside the bankruptcy forum is final and immediately appealable.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"sum":"The Court held that the Constitution allows the Federal Government to administer antipsychotic drugs, even against the defendant's will, in limited circumstances.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Thryv, Inc. v. Click-To-Call Technologies, LP","cite":"590 U.S. 45","y":2020,"id":"2019/18-916","sc":1,"sum":"The Court held that 35 U.S.C. §314(d) precludes judicial review of a Patent Trial and Appeal Board’s decision to institute inter partes review upon finding that §315(b)’s time bar did not apply.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Trump v. United States","cite":"603 U.S. 593","y":2024,"id":"2023/23-939","sc":1,"op":2,"ar":1,"sum":"The nature of Presidential power entitles a former President to absolute immunity from criminal prosecution for actions within his conclusive and preclusive constitutional authority; he is also entitled to at least presumptive immunity from prosecution for all his official acts; there is no immunity for unofficial acts.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"14, 28","3":"11"}},{"t":"case","label":"United States v. Gooding","cite":"25 U.S. 460","y":1827,"id":"scdb/1827-045","sc":1,"sum":"The United States against Gooding.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"United States v. Hollywood Motor Car Co.","cite":"458 U.S. 263","y":1982,"id":"1981/81-1144","sc":1,"op":2,"sum":"The Court of Appeals was without jurisdiction under 28 U. S. C. § 1291 to review the District Court's interlocutory order refusing to dismiss the indictment. The policy embodied in § 1291 is inimical to piecemeal appellate review of trial court decisions that do not terminate the litigation, and this policy is at its strongest in the field of criminal law. Respondents' claim of prosecutorial vindictiveness does not …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24, 27"}},{"t":"case","label":"United States v. Shaw","cite":"309 U.S. 495","y":1940,"id":"scdb/1939-063","sc":1,"op":4,"sum":"Noting without disagreement that the lower court exercised jurisdiction over the case.","sumSrc":"opinion","by":{"2":"20"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"sum":"The Quiet Title Act’s 12-year statute of limitations, 28 U. S. C. §2409a(g), is a nonjurisdictional claims-processing rule.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"26"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"2":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"2":"32"}},{"t":"case","label":"Adkisson v. Jacobs Eng’g Grp., Inc.","cite":"36 F.4th 686","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/36/686/","by":{"3":"24"}},{"t":"case","label":"Crowson v. Wash. Cnty.","cite":"983 F.3d 1166","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/1166/","by":{"3":"24"}},{"t":"case","label":"Cunningham v. Gen. Dynamics Corp.","cite":"888 F.3d 640","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/888/640/","by":{"3":"19, 20"}},{"t":"case","label":"F. Hoffmann-La-Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"3":"14, 17"}},{"t":"case","label":"Farmer v. Moritsugu","cite":"163 F.3d 610","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/163/610/","by":{"3":"20"}},{"t":"case","label":"Kawananakoa v. Polyblank","cite":"205 U.S. 349","y":1907,"id":"scdb/1906-123","sc":1,"sum":"Under Equity Rule 92, where a part of the mortgage premises has been sold to the sovereign power which refuses to waive, its exemption from suit, the court can, all other parties being joined, except the land so conveyed and decree sale.of the balance and enter deficiency judgment for sum remaining dueif proceeds of salé are insufficient to pay the debt.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"KBR, Inc. v. Metzgar","cite":"574 U.S. 1120","y":2015,"url":"https://supreme.justia.com/cases/federal/us/574/1120/","sc":1,"by":{"3":"12, 12"}},{"t":"case","label":"Knick v. Twp. of Scott","cite":"588 U.S. 180","y":2019,"url":"https://supreme.justia.com/cases/federal/us/588/180/","sc":1,"by":{"3":"4, 5, 8"}},{"t":"case","label":"Lewis v. Clarke","cite":"581 U.S. 155","y":2017,"id":"2016/15-1500","sc":1,"sum":"The Court determined that tribal sovereign immunity is not implicated in a suit against a tribal employee in his individual capacity, and an indemnification provision cannot extend tribal sovereign immunity to conduct that it would not otherwise cover.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"Mathis v. United States","cite":"579 U.S. 500","y":2016,"id":"2015/15-6092","sc":1,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Nwauzor v. GEO Grp., Inc.","cite":"146 F.4th 1280","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/146/1280/","ar":1,"by":{"3":"23"}},{"t":"case","label":"Riggs v. UCOR, LLC","cite":"2024 WL 3634471","y":2024,"court":"Aug. 2, 2024, 6th Cir.","by":{"3":"24"}},{"t":"case","label":"Sanzone v. Gray","cite":"884 F.3d 736","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/884/736/","sum":"Noting this standard but reversing because the given facts supported immunity.","sumSrc":"brief:3","by":{"3":"20"}},{"t":"case","label":"Yousef v. Samantar","cite":"699 F.3d 763","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/699/763/","by":{"3":"11"}},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","subs":["(a)(1)(B)"],"by":{"3":"22"}},{"t":"reg","label":"48 C.F.R. § 31.205","url":"https://www.ecfr.gov/current/title-48/section-31.205","by":{"3":"22"}},{"t":"case","label":"Br. of the U.S., Childs v. San Diego Family Housing LLC","cite":"2021 WL 1897312","y":2021,"court":"9th Cir.","ar":1,"by":{"3":"16"}}]};